insert into public.site_content(id,content_key,title,subtitle,body,image_url,image_alt,button_label,button_url) values
('30000000-0000-4000-8000-000000000001','hero','El sabor de Ushuaia','USHUAIA · TIERRA DEL FUEGO','Pizzas a la piedra, parrilla y mucho más','https://images.unsplash.com/photo-1579751626657-72bc17010498?auto=format&fit=crop&w=1000&q=85','Pizza a la piedra recién horneada','Ver menú','/#menu'),
('30000000-0000-4000-8000-000000000002','about','Acá, siempre hay lugar para uno más.','TU MESA EN EL FIN DEL MUNDO','Sabores de siempre, porciones para compartir y el calor de una buena mesa. Te esperamos en Magallanes 967, en el corazón de Ushuaia.','https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Calamares_a_la_Romana-2009.jpg/960px-Calamares_a_la_Romana-2009.jpg','Una mesa para compartir','Cómo llegar','https://www.google.com/maps/search/?api=1&query=Magallanes+967+Ushuaia') on conflict do nothing;
insert into public.site_settings(id,business_name,address,instagram_url,logo_url,logo_alt,opening_hours) values ('40000000-0000-4000-8000-000000000001','Dieguito','Magallanes 967, Ushuaia, Tierra del Fuego','https://instagram.com/dieguitoushuaia','https://res.cloudinary.com/dtmziqubb/image/upload/v1789413874/Capa_1_vbysn1.png','Dieguito','[{"day":"Lunes","hours":"Consultar en el local","closed":false},{"day":"Martes","hours":"Consultar en el local","closed":false},{"day":"Miércoles","hours":"Consultar en el local","closed":false},{"day":"Jueves","hours":"Consultar en el local","closed":false},{"day":"Viernes","hours":"Consultar en el local","closed":false},{"day":"Sábado","hours":"Consultar en el local","closed":false},{"day":"Domingo","hours":"Consultar en el local","closed":false}]'::jsonb) on conflict do nothing;
insert into public.site_content(id,content_key,title,subtitle,body,image_url,image_alt,button_label,button_url,metadata,is_visible,translations) values('30000000-0000-4000-8000-000000000001','hero','Pizzas a la piedra','DIEGUITO · USHUAIA','Sabores irresistibles, ingredientes seleccionados y ese toque casero que nos caracteriza.','/images/hero/pizza.png','Pizza artesanal a la piedra','Ver pizzas','/#menu-pizzas','{"category_slug":"pizzas","sort_order":0}'::jsonb,true,'{"pt":{"title":"Pizzas na pedra","body":"Sabores irresistíveis, ingredientes selecionados e aquele toque caseiro que nos caracteriza.","button_label":"Ver pizzas","image_alt":"Pizza artesanal assada na pedra"},"en":{"title":"Stone-baked pizzas","body":"Irresistible flavors, selected ingredients and our signature homemade touch.","button_label":"View pizzas","image_alt":"Artisan stone-baked pizza"}}'::jsonb) on conflict(content_key) do update set title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,image_url=excluded.image_url,image_alt=excluded.image_alt,button_label=excluded.button_label,button_url=excluded.button_url,metadata=excluded.metadata,is_visible=excluded.is_visible,translations=excluded.translations where public.site_content.title='El sabor de Ushuaia';
