-- Retirar únicamente registros identificados del seed de demostración anterior.
delete from public.promotions where id='20000000-0000-4000-8000-000000000001' and title='Hoy se comparte';
delete from public.products where id::text like '10000000-0000-4000-8000-%' and slug in ('muzzarella','hamburguesa-dieguito','empanada-de-carne','rabas','promo-19');
delete from public.categories c where id::text like '00000000-0000-4000-8000-%' and slug in ('promos','entradas','milanesas-del-bodegon','calzones','menu-del-dia') and not exists(select 1 from public.products p where p.category_id=c.id);
commit;

