update public.site_content set translations='{"pt":{"title":"Aqui sempre há lugar para mais um.","subtitle":"SUA MESA NO FIM DO MUNDO","body":"Sabores de sempre, porções para compartilhar e o aconchego de uma boa mesa. Esperamos você na Magallanes 967, no coração de Ushuaia.","button_label":"Como chegar","image_alt":"Uma mesa para compartilhar"},"en":{"title":"There is always room for one more here.","subtitle":"YOUR TABLE AT THE END OF THE WORLD","body":"Familiar flavors, portions to share and the warmth of a good table. Visit us at Magallanes 967, in the heart of Ushuaia.","button_label":"Get directions","image_alt":"A table to share"}}'::jsonb where content_key='about' and translations='{}'::jsonb;
